void DriveProcessor::timerCallback(){flushMidiChanges();}
void DriveProcessor::flushMidiChanges(){for(int i=0;i<mapCount;++i){float v=map[i].pending.exchange(-1);if(v>=0)map[i].param->setValueNotifyingHost(v);}}
void DriveProcessor::learn(const String& id){for(int i=0;i<mapCount;++i)if(map[i].param->paramID==id){learnTarget.store(i);return;}}
void DriveProcessor::unlearn(const String& id){for(int i=0;i<mapCount;++i)if(map[i].param->paramID==id)map[i].cc.store(-1);learnTarget.store(-1);}
int DriveProcessor::mapping(const String& id)const{for(int i=0;i<mapCount;++i)if(map[i].param->paramID==id)return map[i].cc.load();return -1;}
void DriveProcessor::initPreset(){for(int i=0;i<mapCount;++i)map[i].param->setValueNotifyingHost(map[i].param->getDefaultValue());selectedPreset=-1;}
