 if(p.engine==0){set("tubeType",float(j%3));set("tubeSag",20.f+5.f*j);}
 if(p.engine==1){set("tapeSpeed",float(j%3));set("tapeMemory",15.f+5.f*j);set("wow",category==2?float(j%3)*2.f:0.f);set("flutter",category==2?float(j%3):0.f);}
 if(p.engine==2)set("edge",25.f+7.f*j);
 if(p.engine==3){set("consoleType",float(j%3));set("headroom",category==9?6.f:0.f);}
 if(p.engine==4){set("antiAlias",1.f);set("fuzzType",float(j%2));set("starve",float(j)*6.f);set("fuzzGate",float(j)*3.f);}
 if(p.engine==5){set("diodeType",float(j%3));set("diodeThreshold",.55f+.04f*j);set("diodeHard",15.f+7.f*j);}
